import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.DnrXFDHb.js";const m=JSON.parse('{"title":"大模型入门","description":"","frontmatter":{},"headers":[],"relativePath":"llm/basics.md","filePath":"llm/basics.md","lastUpdated":null}'),t={name:"llm/basics.md"};function o(p,l,n,s,h,u){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="大模型入门" tabindex="-1">大模型入门 <a class="header-anchor" href="#大模型入门" aria-label="Permalink to &quot;大模型入门&quot;">​</a></h1><p>一句话：LLM 是以大量文本和代码训练出来的语言模型，核心能力是根据上下文预测和生成后续 token。</p><h2 id="llm-是什么" tabindex="-1">LLM 是什么 <a class="header-anchor" href="#llm-是什么" aria-label="Permalink to &quot;LLM 是什么&quot;">​</a></h2><p>LLM 是 Large Language Model，大语言模型。它可以处理和生成自然语言，也常能处理代码、表格、结构化文本，部分模型还能理解图片、音频或视频。</p><p>它擅长：</p><ul><li>总结、改写、翻译。</li><li>问答和解释。</li><li>代码生成和调试。</li><li>信息抽取和结构化。</li><li>规划步骤和辅助决策。</li></ul><p>它不擅长：</p><ul><li>自动保证事实正确。</li><li>长期稳定记住所有历史。</li><li>在缺少上下文时猜测私有信息。</li><li>对所有数学、逻辑和最新事实都零错误。</li></ul><h2 id="为什么它能对话" tabindex="-1">为什么它能对话 <a class="header-anchor" href="#为什么它能对话" aria-label="Permalink to &quot;为什么它能对话&quot;">​</a></h2><p>LLM 的基本训练目标通常是预测下一个 token。大量训练后，模型会学到语言模式、知识关联、代码结构、推理模板和交互习惯。</p><p>对话能力通常来自后续训练和对齐：</p><ul><li>指令微调：让模型更会按人类指令回答。</li><li>偏好对齐：让模型更符合人类偏好的表达、安全和帮助性。</li><li>工具调用训练：让模型学会在需要时调用外部工具。</li></ul><h2 id="prompt-的作用" tabindex="-1">Prompt 的作用 <a class="header-anchor" href="#prompt-的作用" aria-label="Permalink to &quot;Prompt 的作用&quot;">​</a></h2><p>Prompt 不是命令开关，而是提供任务、上下文、约束和输出格式。</p><p>好的 Prompt 通常包含：</p><ul><li>目标：要解决什么问题。</li><li>背景：必要上下文和材料。</li><li>约束：不要做什么、必须遵守什么。</li><li>输出格式：希望返回表格、列表、JSON 还是步骤。</li><li>判断标准：什么算完成。</li></ul><h2 id="幻觉和不确定性" tabindex="-1">幻觉和不确定性 <a class="header-anchor" href="#幻觉和不确定性" aria-label="Permalink to &quot;幻觉和不确定性&quot;">​</a></h2><p>幻觉是模型生成了看似合理但不真实的内容。它常出现在：</p><ul><li>问题缺少上下文。</li><li>资料已经过期。</li><li>要求模型给出不存在的引用。</li><li>任务需要外部验证但没有提供工具。</li></ul><p>降低幻觉的方法：</p><ul><li>提供原始资料。</li><li>要求模型区分事实、推断和不确定。</li><li>对最新信息进行检索。</li><li>使用 RAG 或数据库查询。</li><li>对关键输出做测试或人工复核。</li></ul><h2 id="llm-应用的基本形态" tabindex="-1">LLM 应用的基本形态 <a class="header-anchor" href="#llm-应用的基本形态" aria-label="Permalink to &quot;LLM 应用的基本形态&quot;">​</a></h2><p>常见应用可以分为几类：</p><ul><li>Chat：对话问答和写作辅助。</li><li>Copilot：在具体软件或代码环境里辅助操作。</li><li>RAG：先检索资料，再让模型基于资料回答。</li><li>Agent：模型会规划步骤并调用工具。</li><li>Workflow：把模型调用放进固定业务流程。</li></ul><p>学习 LLM 时，不要只学聊天技巧，还要理解数据、工具、评估和失败模式。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>阅读 <a href="/llm/transformer">Transformer 直觉</a>，理解模型如何利用上下文。</li><li>阅读 <a href="/prompting/basics">Prompt 入门</a>，把模型能力转化为可验证的任务说明。</li></ul>',27)])])}const c=i(t,[["render",o]]);export{m as __pageData,c as default};
